  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0)
  if (today < roadmapRange.start || today > roadmapRange.end) return
  const span = roadmapRange.end.getTime() - roadmapRange.start.getTime()
  if (span <= 0) return
