  line-height: 1.3;
}
.modal-markdown h1 { font-size: 18px; }
.modal-markdown h2 { font-size: 16px; }
.modal-markdown h3 { font-size: 14px; }
.modal-markdown p {
  margin: 8px 0;
  color: #ddd6df;
}
.modal-markdown ul,
.modal-markdown ol {
  margin: 8px 0;
  padding-left: 20px;
}
.modal-markdown li {
  margin-bottom: 4px;
}
.modal-markdown .md-checklist li {
  list-style: none;
  margin-left: -18px;
}
.modal-markdown .md-checklist li::before {
  content: "[ ]";
  color: var(--muted);
  margin-right: 6px;
}
.modal-markdown .md-checklist li.check.checked::before {
  content: "[x]";
  color: var(--accent);
}
.modal-markdown blockquote {
  margin: 8px 0;
  padding: 2px 0 2px 10px;
  border-left: 2px solid var(--line);
  color: var(--muted);
}
.modal-markdown hr {
  border: 0;
  border-top: 1px solid var(--line);
  margin: 12px 0;
}
.modal-markdown a {
  color: var(--accent);
}
.modal-markdown code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  background: rgba(255, 255, 255, 0.08);
  padding: 1px 4px;
  border-radius: 4px;
}
.modal-markdown pre {
  margin: 8px 0;
  background: #0b0a0c;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  overflow: auto;
}
.modal-markdown pre code {
  background: transparent;
  padding: 0;
}

.log-view {
  margin: 0 12px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px;
  min-height: 24px;
  color: var(--muted);
  font-size: 12px;
  white-space: pre-wrap;
}

.log-view.hidden { display: none; }
.hidden { display: none !important; }

.ok { color: var(--ok); }
.error { color: #ff8f8f; }
.empty { color: var(--muted); font-size: 13px; }

@media (max-width: 900px) {
  .topbar {
    grid-template-columns: 1fr;
  }
  #roadmap-view {
    height: calc(100vh - 146px);
  }
  .timeline-header, .milestone-header, .task-row {
    grid-template-columns: 180px 1fr;
  }
}

