    setModalContent(`<section class="modal-section"><h3>Task info</h3>${head}${parentHeadRow}${subtasksHeadRow}</section><section class="modal-section"><h3>Detail file</h3><div class="modal-row"><span>Path</span><strong>${escapeHtml(detail?.path || task.detailPath)}</strong></div>${summary}${steps ? `<ul class="modal-steps">${steps}</ul>` : '<p class="modal-empty">No checklist steps found.</p>'}${desc || '<p class="modal-empty">No description found.</p>'}${markdown || '<p class="modal-empty">Could not render markdown.</p>'}${raw}</section>`)
