  if (!task.detailPath) {
    setModalContent(`<section class="modal-section"><h3>Task info</h3>${head}${parentHeadRow}${subtasksHeadRow}</section>`)
    return
  }
  try {
    const detail = await loadTaskDetail(task)
    const steps = (detail?.steps || [])
      .map((step) => `<li class="${step.done ? "done" : ""}">${escapeHtml(step.text)}</li>`)
      .join("")
    const summary = detail?.summary ? `<div class="modal-row"><span>Summary</span><strong>${escapeHtml(detail.summary)}</strong></div>` : ""
    const desc = detail?.description ? `<pre class="modal-pre">${escapeHtml(detail.description)}</pre>` : ""
    const markdown = detail?.html ? `<div class="modal-markdown">${detail.html}</div>` : ""
    const raw = detail?.raw ? `<details><summary>Raw detail markdown</summary><pre class="modal-pre">${escapeHtml(detail.raw)}</pre></details>` : ""
    setModalContent(`<section class="modal-section"><h3>Task info</h3>${head}${parentHeadRow}${subtasksHeadRow}</section><section class="modal-section"><h3>Detail file</h3><div class="modal-row"><span>Path</span><strong>${escapeHtml(detail?.path || task.detailPath)}</strong></div>${summary}${steps ? `<ul class="modal-steps">${steps}</ul>` : '<p class="modal-empty">No checklist steps found.</p>'}${desc || '<p class="modal-empty">No description found.</p>'}${markdown || '<p class="modal-empty">Could not render markdown.</p>'}${raw}</section>`)
  } catch (error) {
