    setModalContent(`<section class="modal-section"><h3>Task info</h3>${head}${parentHeadRow}${subtasksHeadRow}</section><section class="modal-section"><h3>Detail file</h3><p class="modal-error">${escapeHtml(message)}</p></section>`)
  }
}

async function loadBoard() {
