}

.task-ref-link {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
  color: var(--text);
  border-radius: 999px;
  padding: 2px 10px;
  cursor: pointer;
  font-size: 11px;
}

.task-ref-link:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.roadmap-surface {
  border: 1px solid var(--line);
  border-radius: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0));
  overflow-x: auto;
  overflow-y: auto;
  padding: 8px;
  width: 100%;
  height: 100%;
}
.timeline { position: relative; min-width: 100%; }
.timeline-header, .milestone-header, .task-row {
  display: grid;
  grid-template-columns: 260px 1fr;
}
.timeline-header {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
}
.timeline-label, .milestone-label, .task-label {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--panel);
  padding: 8px 12px;
}
.timeline-label { color: var(--muted); font-size: 11px; }
.timeline-grid {
  position: relative;
  height: 46px;
}
.timeline-grid-line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: rgba(127, 127, 127, 0.25);
}
.timeline-grid-label {
  position: absolute;
  top: 7px;
  transform: translateX(-50%);
  font-size: 10px;
  color: var(--muted);
  white-space: nowrap;
}
.timeline-grid-label-day {
  top: 30px;
  opacity: 0.85;
}

.timeline-grid-label-day.today {
  color: #ff6b6b;
  font-weight: 600;
}
.milestone-group { margin-bottom: 8px; }
.milestone-header {
  border-top: 1px solid var(--line);
  align-items: center;
}
.milestone-line {
  height: 1px;
  background: var(--line);
  margin-top: 18px;
}
.task-row {
  align-items: center;
  min-height: 42px;
  border-top: 1px solid rgba(127, 127, 127, 0.2);
}
.task-row-alt { background: var(--roadmap-row); }
.task-label {
  font-size: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.task-id { color: var(--muted); }
.task-status {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 10px;
}
.task-bar-area {
  position: relative;
  height: 30px;
}
.task-bar {
  position: absolute;
  top: 6px;
  height: 18px;
  border-radius: 999px;
  background: rgba(34, 197, 94, 0.2);
  overflow: hidden;
}
.task-bar-progress {
  height: 100%;
  background: linear-gradient(90deg, #22c55e, #86efac);
}

.today-line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: #4caf50;
  z-index: 1;
}

.today-badge {
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  background: #4caf50;
  color: #fff;
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 999px;
}

.modal {
  position: fixed;
  inset: 0;
  display: none;
  z-index: 30;
}
.modal.open {
  display: block;
}
.modal-backdrop {
  position: absolute;
