:root {
  --bg: #0f0d0f;
  --panel: #151216;
  --panel-2: #1d1820;
  --line: #312a34;
  --text: #e9e3ec;
  --muted: #a89eaf;
  --accent: #a7f3c3;
  --accent-strong: #22c55e;
  --ok: #8df0bc;
  --roadmap-row: rgba(167, 243, 195, 0.06);
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: "IBM Plex Sans", "Segoe UI", sans-serif;
  color: var(--text);
  background: radial-gradient(900px 540px at 0% -12%, #1b1620 0%, var(--bg) 52%);
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
  background: rgba(15, 13, 15, 0.92);
  backdrop-filter: blur(6px);
}

.title-group { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.title-group h1 { margin: 0; font-size: 15px; }

.mode-badge {
  border: 1px solid rgba(34, 197, 94, 0.5);
  color: #a7f3c3;
  border-radius: 999px;
  padding: 2px 8px;
  font-size: 11px;
}

#board-meta { color: var(--muted); font-size: 12px; }

.actions, .view-switcher { display: flex; gap: 8px; align-items: center; }

.zoom-controls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.zoom-label {
  font-size: 11px;
  color: var(--muted);
}

.zoom-select {
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--text);
  border-radius: 8px;
  padding: 6px 8px;
  font-size: 12px;
}

.btn, .tab {
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--text);
  border-radius: 8px;
  padding: 6px 10px;
  cursor: pointer;
}

.tab.active, .btn:hover {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.26);
}

.toggle-btn.active {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.26);
  color: var(--text);
}

.view { display: none; padding: 12px; }
.view.active { display: block; }

main { min-height: calc(100vh - 62px); }

#roadmap-view {
  padding: 0;
  height: calc(100vh - 102px);
}

.kanban-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 10px;
}

.col { border: 1px solid var(--line); border-radius: 10px; background: var(--panel); overflow: hidden; }
.col-head { display: flex; justify-content: space-between; padding: 10px; background: var(--panel-2); border-bottom: 1px solid var(--line); }
.col-head h3 { margin: 0; font-size: 13px; }
.count { color: var(--muted); font-size: 12px; }

.cards { display: flex; flex-direction: column; gap: 8px; padding: 10px; }
.card { border: 1px solid var(--line); border-radius: 8px; padding: 8px; background: rgba(255, 255, 255, 0.02); }
.card-head {
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  text-align: left;
  padding: 0;
  cursor: pointer;
}
.card-title { font-size: 13px; font-weight: 600; margin-bottom: 6px; }
.expander {
  font-size: 11px;
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 1px 8px;
}
.card.expanded .expander {
  color: var(--text);
  border-color: var(--accent);
}
.card-meta { display: flex; flex-wrap: wrap; gap: 6px; }
.card-details {
  margin-top: 8px;
  border-top: 1px solid var(--line);
  padding-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
