const STATUS_ORDER = ["backlog", "doing", "review", "done", "paused", "unknown"]
const ONE_DAY_MS = 24 * 60 * 60 * 1000
const RANGE_PADDING_DAYS = 7
const DEFAULT_DURATION_DAYS = 7
