  padding: 2px 8px;
  font-size: 11px;
}

#board-meta { color: var(--muted); font-size: 12px; }

.actions, .view-switcher { display: flex; gap: 8px; align-items: center; }

.zoom-controls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.zoom-label {
  font-size: 11px;
