  min-height: 16px;
}
.task-id { color: var(--muted); }
.task-status {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 10px;
}
.task-open-link {
  border: 0;
  background: transparent;
  color: var(--text);
  text-align: left;
  padding: 0;
